import { useEffect, useState } from "react";
import {
  Users, Plus, Filter, BarChart3, TrendingUp, DollarSign,
  Calendar, UserCog, Download, FileSpreadsheet, Search, X, Leaf,
} from "lucide-react";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { PermissionBlur } from "@/shared/ui/PermissionBlur";
import { useStore } from "@/shared/contexts/StoreContext";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/shared/ui/badge";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Textarea } from "@/shared/ui/textarea";
import { Label } from "@/shared/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/shared/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover";
import { Calendar as CalendarComponent } from "@/shared/ui/calendar";
import { Checkbox } from "@/shared/ui/checkbox";
import { cn } from "@/shared/lib/utils";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import * as XLSX from "xlsx";
import { WorkReportsModal } from "./WorkReportsModal";

/* ── tipos ──────────────────────────────────────────────────────────────── */

interface Freelancer {
  id: string;
  nome: string;
  cpf: string;
  valorDiaria: number;
  diasTrabalhados: Date[];
  diasDetalhados?: { data: Date; valor: number; lojaId?: number | null }[];
  chavePix: string;
  totalRecebido: number;
  dataUltimoTrabalho: string;
  status: 'ativo' | 'inativo';
}

interface AvulsoWork {
  id: string;
  nome: string;
  work_date: string;
  valor_diaria: number;
  loja_id: number | null;
  local_tipo: string | null;
  evento_nome: string | null;
  setor: string | null;
  observacao: string | null;
  created_at?: string | null;
}

/* ── tokens de design (mesmos de Funcionarios.page.tsx) ─────────────────── */

const GLASS_CARD  = "bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[28px] shadow-sm";
const GLASS_FILTER= "bg-white/40 dark:bg-zinc-900/40 backdrop-blur-md border border-[#57715B]/10 dark:border-white/5 rounded-3xl p-4 shadow-sm";
const INPUT_CLS   = "bg-white/60 dark:bg-zinc-900/60 border-[#57715B]/20 dark:border-white/10 rounded-2xl h-10 focus-visible:ring-[#57715B]/30";
const BTN_PRIMARY = "rounded-2xl bg-[#57715B] hover:bg-[#4a6450] text-white shadow-md shadow-[#57715B]/20";
const BTN_OUTLINE = "rounded-2xl border-[#57715B]/30 text-[#57715B] dark:text-[#8FA893] hover:bg-[#57715B]/10";
const SEL_CONTENT = "rounded-2xl border-[#57715B]/10 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl";

/* ── KPI card (igual ao padrão de Funcionarios) ─────────────────────────── */

function KpiCard({ label, value, color, sub }: { label: string; value: string | number; color: string; sub?: string }) {
  return (
    <div className="bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[24px] p-5 shadow-sm hover:shadow-md transition-all">
      <p className="text-xs uppercase tracking-widest font-medium text-[#8C7B6D] dark:text-[#9BA59C] opacity-80">{label}</p>
      <p className="text-4xl font-bold mt-2 font-serif" style={{ color }}>{value}</p>
      {sub && <p className="text-xs text-[#8C7B6D] dark:text-[#9BA59C] mt-1">{sub}</p>}
    </div>
  );
}

/* ── página ─────────────────────────────────────────────────────────────── */

export default function FreelancersPage() {
  const { loading } = useStore();
  const { isAdmin, hasPermission } = usePermissions();

  const [freelancers, setFreelancers] = useState<Freelancer[]>([]);
  const [stores, setStores]   = useState<{ id: number; nome: string }[]>([]);
  const storesMap = Object.fromEntries(stores.map(s => [s.id, s.nome]));

  /* filtros fixos */
  const [filtroNome,   setFiltroNome]   = useState("");
  const [filtroCpf,    setFiltroCpf]    = useState("");
  const [filtroStatus, setFiltroStatus] = useState("todos");
  const [lojaFilter,   setLojaFilter]   = useState("all");

  /* avulsos */
  const [avulsos,          setAvulsos]          = useState<AvulsoWork[]>([]);
  const [avulsoNome,       setAvulsoNome]        = useState("");
  const [avulsoLojaFilter, setAvulsoLojaFilter]  = useState("all");
  const [avulsoDateStart,  setAvulsoDateStart]   = useState("");
  const [avulsoDateEnd,    setAvulsoDateEnd]     = useState("");

  /* dialogs */
  const [isDialogOpen,      setIsDialogOpen]      = useState(false);
  const [isAvulsoDialogOpen,setIsAvulsoDialogOpen]= useState(false);
  const [isExportDialogOpen,setIsExportDialogOpen]= useState(false);
  const [isWorkReportsOpen, setIsWorkReportsOpen] = useState(false);
  const [editFreelancer,    setEditFreelancer]    = useState<Freelancer | null>(null);
  const [viewFreelancer,    setViewFreelancer]    = useState<Freelancer | null>(null);
  const [addWorkFreelancer, setAddWorkFreelancer] = useState<Freelancer | null>(null);

  /* forms */
  const [novoFreelancer, setNovoFreelancer] = useState({ nome:'', cpf:'', valorDiaria:'', diasTrabalhados:[] as Date[], chavePix:'', lojaId:'' });
  const [novoAvulso,     setNovoAvulso]     = useState({ nome:'', valorDiaria:'', workDate:'', lojaId:'', localTipo:'loja', eventoNome:'', setor:'', observacao:'' });

  /* registrar trabalho */
  const [workDias,       setWorkDias]       = useState<Date[]>([]);
  const [workValorDiaria,setWorkValorDiaria]= useState('');
  const [workLojaId,     setWorkLojaId]     = useState('');
  const [workLocalTipo,  setWorkLocalTipo]  = useState<'loja'|'evento'>('loja');
  const [workEventoNome, setWorkEventoNome] = useState('');
  const [workSetor,      setWorkSetor]      = useState('');
  const [workObservacao, setWorkObservacao] = useState('');

  /* analytics */
  const [periodo,      setPeriodo]      = useState<'mes_atual'|'mes_anterior'|'ultimos_7'|'personalizado'>('mes_atual');
  const [periodoRange, setPeriodoRange] = useState<{from?:Date;to?:Date}>({});

  /* export */
  const [selectedFreelancerIds, setSelectedFreelancerIds] = useState<string[]>([]);
  const [selectedAvulsoIds,     setSelectedAvulsoIds]     = useState<string[]>([]);
  const [exportMode,  setExportMode]  = useState<'mes_atual'|'mes_anterior'|'mes'|'intervalo'>('mes_atual');
  const [exportMonth, setExportMonth] = useState(new Date().getMonth()+1);
  const [exportYear,  setExportYear]  = useState(new Date().getFullYear());
  const [exportRange, setExportRange] = useState<{from?:Date;to?:Date}>({});
  const [includeResumo,    setIncludeResumo]    = useState(true);
  const [includeDetalhado, setIncludeDetalhado] = useState(true);
  const [detalhadoColumns, setDetalhadoColumns] = useState({ nome:true, cpf:true, data:true, valor:true, loja:true, chavePix:false });

  /* ── utils ── */
  const parseDateLocal = (s: string): Date => {
    if (!s) return new Date(NaN);
    const [y, m, d] = s.split('-').map(Number);
    return new Date(y, m-1, Number(String(d).slice(0,2)));
  };
  const isWithinRange = (date: Date, from?: Date, to?: Date) => {
    if (!from || !to) return true;
    const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    return d >= new Date(from.getFullYear(), from.getMonth(), from.getDate())
        && d <= new Date(to.getFullYear(),   to.getMonth(),   to.getDate());
  };
  const getPeriodoRange = () => {
    const n = new Date();
    if (periodo==='mes_atual')    return { from: new Date(n.getFullYear(), n.getMonth(),1),   to: new Date(n.getFullYear(), n.getMonth()+1, 0) };
    if (periodo==='mes_anterior') return { from: new Date(n.getFullYear(), n.getMonth()-1,1), to: new Date(n.getFullYear(), n.getMonth(),   0) };
    if (periodo==='ultimos_7')    { const l=new Date(); l.setDate(l.getDate()-6); return {from:l,to:n}; }
    return { from: periodoRange.from, to: periodoRange.to };
  };
  const getExportRange = () => {
    const n = new Date();
    if (exportMode==='mes_atual')    return { from: new Date(n.getFullYear(), n.getMonth(),1),   to: new Date(n.getFullYear(), n.getMonth()+1, 0) };
    if (exportMode==='mes_anterior') return { from: new Date(n.getFullYear(), n.getMonth()-1,1), to: new Date(n.getFullYear(), n.getMonth(),   0) };
    if (exportMode==='mes')          return { from: new Date(exportYear, exportMonth-1, 1),      to: new Date(exportYear, exportMonth, 0) };
    return { from: exportRange.from, to: exportRange.to };
  };

  /* ── fetch ── */
  useEffect(()=>{ supabase.from('lojas').select('id, nome').order('nome').then(({data})=>setStores(data||[])); },[]);
  useEffect(()=>{ fetchFreelancers(); },[lojaFilter]); // eslint-disable-line
  useEffect(()=>{ fetchAvulsos(); },[avulsoLojaFilter,avulsoDateStart,avulsoDateEnd,avulsoNome]); // eslint-disable-line

  const fetchFreelancers = async () => {
    try {
      const { data: rows, error } = await supabase.from('freelancers').select('*').order('nome');
      if (error) throw error;
      const ids = (rows||[]).map((f:any)=>f.id);
      let workRows:any[] = [];
      if (ids.length) {
        const {data:wr} = await supabase.from('freelancer_work_days').select('freelancer_id, work_date, valor_diaria, loja_id').in('freelancer_id', ids);
        workRows = wr||[];
      }
      const byId:Record<string,any[]>={};
      for(const wr of workRows){ if(!byId[wr.freelancer_id]) byId[wr.freelancer_id]=[]; byId[wr.freelancer_id].push(wr); }
      setFreelancers((rows||[]).map((fr:any)=>{
        const items = byId[fr.id]||[];
        const diasDetalhados = items.map((d:any)=>({ data: parseDateLocal(d.work_date), valor: Number(d.valor_diaria??fr.valor_diaria??0), lojaId: d.loja_id??null }));
        const diasTrabalhados = diasDetalhados.map(d=>d.data);
        const ultimoDia = diasTrabalhados.length ? new Date(Math.max(...diasTrabalhados.map(d=>d.getTime()))) : null;
        return { id:fr.id, nome:fr.nome, cpf:fr.cpf, valorDiaria:Number(fr.valor_diaria??0), diasTrabalhados, diasDetalhados, chavePix:fr.chave_pix, totalRecebido:items.reduce((s:number,d:any)=>s+Number(d.valor_diaria??fr.valor_diaria??0),0), dataUltimoTrabalho: ultimoDia ? format(ultimoDia,'yyyy-MM-dd') : '', status:(fr.status as 'ativo'|'inativo')??' ativo' };
      }));
    } catch(err){ console.error('[Freelancers]',err); }
  };

  const fetchAvulsos = async () => {
    try {
      let q = supabase.from('freelancer_avulso_work_days').select('*');
      if (avulsoDateStart) q = q.gte('work_date', avulsoDateStart);
      if (avulsoDateEnd)   q = q.lte('work_date', avulsoDateEnd);
      if (avulsoLojaFilter!=='all') q = q.eq('loja_id', Number(avulsoLojaFilter));
      if (avulsoNome.trim())        q = q.ilike('nome',`%${avulsoNome.trim()}%`);
      const {data,error} = await q.order('work_date',{ascending:false});
      if (error) throw error;
      setAvulsos((data as AvulsoWork[])||[]);
    } catch(err){ console.error('[Freelancers]',err); }
  };

  /* ── mutations ── */
  const handleAdicionarFreelancer = async () => {
    if (!novoFreelancer.nome||!novoFreelancer.cpf||!novoFreelancer.chavePix){ alert('Preencha nome, CPF e chave PIX'); return; }
    try {
      const {data:{user}} = await supabase.auth.getUser();
      if (!user){ alert('Autentique-se primeiro'); return; }
      const {error} = await supabase.from('freelancers').insert({ nome:novoFreelancer.nome, cpf:novoFreelancer.cpf, valor_diaria:parseFloat(novoFreelancer.valorDiaria||'0'), chave_pix:novoFreelancer.chavePix, status:'ativo', loja_id:novoFreelancer.lojaId?Number(novoFreelancer.lojaId):null, created_by:user.id });
      if (error) throw error;
      setNovoFreelancer({nome:'',cpf:'',valorDiaria:'',diasTrabalhados:[],chavePix:'',lojaId:''});
      setIsDialogOpen(false);
      await fetchFreelancers();
    } catch(err){ console.error(err); alert('Erro ao adicionar'); }
  };

  const handleUpdateFreelancer = async () => {
    if (!editFreelancer) return;
    try {
      const {error} = await supabase.from('freelancers').update({ nome:editFreelancer.nome, cpf:editFreelancer.cpf, valor_diaria:editFreelancer.valorDiaria, chave_pix:editFreelancer.chavePix, status:editFreelancer.status }).eq('id',editFreelancer.id);
      if (error) throw error;
      setEditFreelancer(null); await fetchFreelancers();
    } catch(err){ console.error(err); }
  };

  const handleDeleteFreelancer = async (id:string) => {
    try {
      await supabase.from('freelancer_work_days').delete().eq('freelancer_id',id);
      const {error} = await supabase.from('freelancers').delete().eq('id',id);
      if (error) throw error;
      await fetchFreelancers();
    } catch(err){ console.error(err); }
  };

  const handleSalvarTrabalho = async () => {
    if (!addWorkFreelancer) return;
    if (!workDias.length){ alert('Selecione ao menos um dia'); return; }
    if (workLocalTipo==='loja'&&!workLojaId){ alert('Selecione a loja'); return; }
    if (workLocalTipo==='evento'&&!workEventoNome.trim()){ alert('Informe o evento'); return; }
    const valorNum = parseFloat(workValorDiaria);
    if (isNaN(valorNum)||valorNum<=0){ alert('Valor inválido'); return; }
    if (!['PRODUÇÃO','ATENDIMENTO','APOIO','EVENTO'].includes(workSetor)){ alert('Selecione o setor'); return; }
    try {
      const {data:{user}} = await supabase.auth.getUser();
      const {error} = await supabase.from('freelancer_work_days').insert(workDias.map(d=>({ freelancer_id:addWorkFreelancer.id, work_date:format(d,'yyyy-MM-dd'), valor_diaria:valorNum, loja_id:workLocalTipo==='loja'?Number(workLojaId):null, local_tipo:workLocalTipo, evento_nome:workLocalTipo==='evento'?workEventoNome.trim():null, setor:workSetor, observacao:workObservacao?.trim()||null, created_by:user?.id })));
      if (error) throw error;
      resetWorkDialog(); await fetchFreelancers();
    } catch(err){ console.error(err); alert('Erro ao registrar'); }
  };

  const resetWorkDialog = () => { setAddWorkFreelancer(null); setWorkDias([]); setWorkValorDiaria(''); setWorkLojaId(''); setWorkLocalTipo('loja'); setWorkEventoNome(''); setWorkSetor(''); setWorkObservacao(''); };

  const handleExportExcel = () => {
    const {from,to} = getExportRange();
    const sel   = selectedFreelancerIds.length ? freelancers.filter(f=>selectedFreelancerIds.includes(f.id)) : freelancersFiltrados;
    const selAv = selectedAvulsoIds.length     ? avulsos.filter(a=>selectedAvulsoIds.includes(a.id))         : avulsos;
    const wb = XLSX.utils.book_new();
    if (includeResumo) {
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(sel.map(f=>{ const dias=(f.diasDetalhados||[]).filter(d=>isWithinRange(d.data,from,to)); return {Nome:f.nome,CPF:f.cpf,Dias:dias.length,'Total (R$)':+dias.reduce((s,d)=>s+d.valor,0).toFixed(2),'Diária (R$)':+(f.valorDiaria||0).toFixed(2),PIX:f.chavePix}; })), 'Resumo');
    }
    if (includeDetalhado) {
      const rows:Record<string,unknown>[]=[];
      for(const f of sel) for(const d of (f.diasDetalhados||[]).filter(d=>isWithinRange(d.data,from,to))){ const r:Record<string,unknown>={}; if(detalhadoColumns.nome) r['Nome']=f.nome; if(detalhadoColumns.cpf) r['CPF']=f.cpf; if(detalhadoColumns.data) r['Data']=format(d.data,'yyyy-MM-dd'); if(detalhadoColumns.loja) r['Loja']=d.lojaId!=null?(storesMap[d.lojaId]||''):''; if(detalhadoColumns.valor) r['Valor (R$)']=+d.valor.toFixed(2); if(detalhadoColumns.chavePix) r['PIX']=f.chavePix; rows.push(r); }
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), 'Detalhado');
    }
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(selAv.map(a=>({Nome:a.nome,Data:format(new Date(a.work_date),'yyyy-MM-dd'),Loja:a.loja_id!=null?(storesMap[a.loja_id]||''):'',Valor:+(a.valor_diaria||0).toFixed(2),Tipo:a.local_tipo||'',Evento:a.evento_nome||'',Setor:a.setor||'',Obs:a.observacao||''}))), 'Avulsos');
    const lbl = exportMode==='mes_atual'?'mes_atual':exportMode==='mes_anterior'?'mes_anterior':exportMode==='mes'?`${String(exportMonth).padStart(2,'0')}-${exportYear}`:`${exportRange.from?format(exportRange.from,'yyyy-MM-dd'):'inicio'}_a_${exportRange.to?format(exportRange.to,'yyyy-MM-dd'):'fim'}`;
    XLSX.writeFile(wb,`freelancers_${lbl}.xlsx`);
    setIsExportDialogOpen(false);
  };

  /* ── computed ── */
  const freelancersFiltrados = freelancers.filter(f =>
    f.nome.toLowerCase().includes(filtroNome.toLowerCase()) &&
    f.cpf.toLowerCase().includes(filtroCpf.toLowerCase()) &&
    (filtroStatus==='todos'||f.status===filtroStatus)
  );

  const {from:rangeFrom, to:rangeTo} = getPeriodoRange();
  const totalFreelancers  = freelancers.length;
  const freelancersAtivos = freelancers.filter(f=>f.status==='ativo').length;
  const totalPago   = freelancers.reduce((acc,f)=>acc+(f.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).reduce((s,d)=>s+d.valor,0),0);
  const mediaDias   = totalFreelancers ? freelancers.reduce((a,f)=>a+(f.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).length,0)/totalFreelancers : 0;
  const maisTrabalhou = freelancers.reduce((p,c)=>((p.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).length>=(c.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).length?p:c), freelancers[0]);
  const maisRecebeu   = freelancers.reduce((p,c)=>((p.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).reduce((s,d)=>s+d.valor,0)>=(c.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).reduce((s,d)=>s+d.valor,0)?p:c), freelancers[0]);

  const listarUltimosDias = (datas:Date[]) => !datas?.length ? '—' : [...datas].sort((a,b)=>b.getTime()-a.getTime()).slice(0,5).map(d=>format(d,'dd/MM',{locale:ptBR})).join(', ');
  const totalRecebidoMesAtual = (f:Freelancer) => { const n=new Date(); return (f.diasDetalhados||[]).filter(d=>d.data.getMonth()===n.getMonth()&&d.data.getFullYear()===n.getFullYear()).reduce((s,d)=>s+d.valor,0); };

  if (loading && stores.length===0) return (
    <div className="flex items-center justify-center min-h-screen bg-white dark:bg-[#0A0A0A]">
      <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-[#57715B]" />
    </div>
  );

  /* ──────────────────────────── RENDER ──────────────────────────────────── */
  return (
    <PermissionBlur hasPermission={isAdmin() || hasPermission('view_funcionarios')} moduleName="Freelancers">
      <div
        className="flex flex-col min-h-screen w-full bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans transition-colors duration-300"
        style={{ backgroundColor: '#ffffff' }}
      >
        {/* faixa verde topo */}
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 pointer-events-none" />

        {/* folhas animadas + glows de fundo */}
        <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
          <div className="absolute top-[25%] left-[10%] w-[350px] h-[350px] opacity-[0.03] dark:opacity-[0.05] animate-pulse" style={{ animationDuration: '10s' }}>
            <Leaf className="w-full h-full text-[#57715B] rotate-12" />
          </div>
          <div className="absolute top-[45%] right-[15%] w-[450px] h-[450px] opacity-[0.03] dark:opacity-[0.05] animate-pulse delay-700" style={{ animationDuration: '14s' }}>
            <Leaf className="w-full h-full text-[#57715B] rotate-[60deg]" />
          </div>
          <div className="absolute bottom-[-5%] left-[30%] w-[400px] h-[400px] opacity-[0.03] dark:opacity-[0.05] animate-pulse delay-1000" style={{ animationDuration: '12s' }}>
            <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
          </div>
          <div className="absolute top-[20%] left-[10%] w-[300px] h-[300px] bg-[#57715B]/5 rounded-full blur-[100px]" />
          <div className="absolute bottom-[30%] right-[10%] w-[350px] h-[350px] bg-[#C5A065]/5 rounded-full blur-[100px]" />
        </div>

        <div className="relative z-10 flex-1 flex flex-col px-4 sm:px-6 py-6 space-y-6 animate-in fade-in duration-500 max-w-[1600px] mx-auto w-full">

          {/* ── Header ─────────────────────────────────────────────────── */}
          <div className="space-y-4">
            <div className="flex items-center gap-3 min-w-0">
              <div className="hidden md:flex h-12 w-12 rounded-2xl bg-[#57715B]/10 dark:bg-[#E6DCCF]/10 items-center justify-center shrink-0">
                <UserCog className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
              </div>
              <div className="min-w-0 flex-1">
                <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif mb-1">
                  Freelancers
                </h1>
                <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80">
                  DP/RH · Trabalhadores externos
                </p>
              </div>
            </div>

            <div className="flex items-center justify-between gap-3 flex-wrap">
              <Button variant="outline" className={BTN_OUTLINE} onClick={()=>setIsWorkReportsOpen(true)}>
                <BarChart3 className="h-4 w-4 mr-2" />Relatórios de trabalhos
              </Button>
              <div className="flex items-center gap-2">
                <Button variant="outline" className={BTN_OUTLINE} onClick={()=>setIsExportDialogOpen(true)}>
                  <FileSpreadsheet className="h-4 w-4 mr-2" />Exportar Excel
                </Button>
                <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                  <DialogTrigger asChild>
                    <Button className={BTN_PRIMARY}>
                      <Plus className="h-4 w-4 mr-2" />Novo freelancer
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="sm:max-w-[480px]">
                    <DialogHeader>
                      <DialogTitle>Adicionar Freelancer</DialogTitle>
                      <DialogDescription>Dados básicos. Dias trabalhados são registrados depois.</DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                      {([['nome','Nome','Nome completo'],['cpf','CPF','000.000.000-00'],['chavePix','Chave PIX','email ou telefone']] as const).map(([field,label,ph])=>(
                        <div key={field} className="grid gap-2">
                          <Label>{label}</Label>
                          <Input className={INPUT_CLS} placeholder={ph} value={novoFreelancer[field]} onChange={e=>setNovoFreelancer({...novoFreelancer,[field]:e.target.value})} />
                        </div>
                      ))}
                      <div className="grid gap-2">
                        <Label>Loja principal (opcional)</Label>
                        <Select value={novoFreelancer.lojaId} onValueChange={v=>setNovoFreelancer({...novoFreelancer,lojaId:v})}>
                          <SelectTrigger className={INPUT_CLS}><SelectValue placeholder="Selecionar loja" /></SelectTrigger>
                          <SelectContent className={SEL_CONTENT}>{stores.map(s=><SelectItem key={s.id} value={String(s.id)}>{s.nome}</SelectItem>)}</SelectContent>
                        </Select>
                      </div>
                    </div>
                    <DialogFooter><Button className={BTN_PRIMARY} onClick={handleAdicionarFreelancer}>Adicionar</Button></DialogFooter>
                  </DialogContent>
                </Dialog>
              </div>
            </div>
          </div>

          {/* ── Tabs ─────────────────────────────────────────────────── */}
          <Tabs defaultValue="lista" className="w-full">
            <TabsList className="bg-white/50 dark:bg-zinc-900/50 backdrop-blur-md border border-[#57715B]/10 rounded-2xl p-1 h-12 gap-1 w-full sm:w-auto">
              <TabsTrigger value="lista"    className="rounded-xl data-[state=active]:bg-[#57715B] data-[state=active]:text-white px-5 h-9 font-medium transition-all gap-2"><Users className="h-4 w-4"/>Fixos</TabsTrigger>
              <TabsTrigger value="avulsos"  className="rounded-xl data-[state=active]:bg-[#57715B] data-[state=active]:text-white px-5 h-9 font-medium transition-all">Avulsos</TabsTrigger>
              <TabsTrigger value="analytics"className="rounded-xl data-[state=active]:bg-[#57715B] data-[state=active]:text-white px-5 h-9 font-medium transition-all gap-2"><BarChart3 className="h-4 w-4"/>Analytics</TabsTrigger>
            </TabsList>

            {/* ══ Tab Fixos ═══════════════════════════════════════════════ */}
            <TabsContent value="lista" className="space-y-4 mt-4">
              {/* barra filtros */}
              <div className={cn(GLASS_FILTER,"flex flex-wrap items-center gap-3")}>
                <div className="flex items-center justify-center h-8 w-8 rounded-full bg-[#57715B]/10 shrink-0">
                  <Filter className="h-4 w-4 text-[#57715B]" />
                </div>
                <div className="relative flex-1 min-w-[160px]">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400 pointer-events-none" />
                  <Input placeholder="Buscar por nome..." value={filtroNome} onChange={e=>setFiltroNome(e.target.value)} className={cn(INPUT_CLS,"pl-10 pr-8")} />
                  {filtroNome && <button onClick={()=>setFiltroNome('')} className="absolute right-2 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-zinc-600"><X className="h-4 w-4"/></button>}
                </div>
                <Input placeholder="CPF..." value={filtroCpf} onChange={e=>setFiltroCpf(e.target.value)} className={cn(INPUT_CLS,"w-[140px]")} />
                <Select value={filtroStatus} onValueChange={setFiltroStatus}>
                  <SelectTrigger className={cn(INPUT_CLS,"w-[130px]")}><SelectValue /></SelectTrigger>
                  <SelectContent className={SEL_CONTENT}><SelectItem value="todos">Todos</SelectItem><SelectItem value="ativo">Ativos</SelectItem><SelectItem value="inativo">Inativos</SelectItem></SelectContent>
                </Select>
                <Select value={lojaFilter} onValueChange={setLojaFilter}>
                  <SelectTrigger className={cn(INPUT_CLS,"w-[160px]")}><SelectValue placeholder="Todas as lojas" /></SelectTrigger>
                  <SelectContent className={SEL_CONTENT}><SelectItem value="all">Todas as lojas</SelectItem>{stores.map(s=><SelectItem key={s.id} value={String(s.id)}>{s.nome}</SelectItem>)}</SelectContent>
                </Select>
                {(filtroNome||filtroCpf||filtroStatus!=='todos'||lojaFilter!=='all') && (
                  <button onClick={()=>{setFiltroNome('');setFiltroCpf('');setFiltroStatus('todos');setLojaFilter('all');}} className="text-xs text-[#57715B] hover:underline font-medium">Limpar</button>
                )}
              </div>

              {/* tabela */}
              <div className="bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[32px] overflow-hidden shadow-lg shadow-[#57715B]/5">
                <div className="px-6 py-4 border-b border-[#57715B]/8 flex items-center justify-between">
                  <div>
                    <p className="font-semibold text-[#2D362E] dark:text-[#E6DCCF]">Lista de Freelancers</p>
                    <p className="text-xs text-[#8C7B6D] dark:text-[#9BA59C] mt-0.5">{freelancersFiltrados.length} resultado(s)</p>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-[#57715B]/8 hover:bg-transparent">
                        {['Nome','CPF','Últimos dias','Chave PIX','Status',''].map(h=>(
                          <TableHead key={h} className={cn("text-[#8C7B6D] text-xs uppercase tracking-wider font-medium", h===''&&"text-right")}>{h}</TableHead>
                        ))}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {freelancersFiltrados.length===0 ? (
                        <TableRow>
                          <TableCell colSpan={6} className="text-center py-16 text-[#8C7B6D]">
                            <UserCog className="h-10 w-10 mx-auto mb-3 opacity-20" />
                            <p className="font-medium">Nenhum freelancer encontrado</p>
                            <p className="text-xs mt-1 opacity-60">Adicione um novo ou ajuste os filtros</p>
                          </TableCell>
                        </TableRow>
                      ) : freelancersFiltrados.map(f=>(
                        <TableRow key={f.id} className="border-[#57715B]/8 hover:bg-[#57715B]/3 transition-colors">
                          <TableCell className="font-semibold text-[#2D362E] dark:text-[#E6DCCF]">{f.nome}</TableCell>
                          <TableCell className="text-[#8C7B6D] font-mono text-sm">{f.cpf}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D]">{listarUltimosDias(f.diasTrabalhados)}</TableCell>
                          <TableCell className="max-w-36 truncate text-sm text-[#8C7B6D]">{f.chavePix}</TableCell>
                          <TableCell>
                            <Badge className={cn("rounded-full border text-xs px-2.5 py-0.5 font-medium", f.status==='ativo' ? 'bg-[#57715B]/10 text-[#57715B] border-[#57715B]/20' : 'bg-zinc-100 text-zinc-500 border-zinc-200 dark:bg-zinc-800 dark:text-zinc-400 dark:border-zinc-700')}>
                              {f.status}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex items-center justify-end gap-1">
                              <Button variant="ghost" size="icon" title="Registrar dias" onClick={()=>{ setAddWorkFreelancer(f); setWorkDias([]); setWorkValorDiaria(''); setWorkLojaId(''); }} className="h-8 w-8 rounded-xl hover:bg-[#57715B]/10 text-[#57715B]">
                                <Plus className="h-4 w-4"/>
                              </Button>
                              <Button variant="outline" size="sm" onClick={()=>setViewFreelancer(f)}  className={cn(BTN_OUTLINE,"h-8 text-xs px-3")}>Ver</Button>
                              <Button variant="outline" size="sm" onClick={()=>setEditFreelancer({...f})} className={cn(BTN_OUTLINE,"h-8 text-xs px-3")}>Editar</Button>
                              <Button variant="ghost"   size="sm" onClick={()=>handleDeleteFreelancer(f.id)} className="h-8 text-xs px-3 rounded-xl text-red-500 hover:bg-red-500/10">Excluir</Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            </TabsContent>

            {/* ══ Tab Avulsos ══════════════════════════════════════════════ */}
            <TabsContent value="avulsos" className="space-y-4 mt-4">
              <div className={cn(GLASS_FILTER,"flex flex-wrap items-center gap-3")}>
                <div className="flex items-center justify-center h-8 w-8 rounded-full bg-[#57715B]/10 shrink-0">
                  <Filter className="h-4 w-4 text-[#57715B]" />
                </div>
                <Input placeholder="Nome..." value={avulsoNome} onChange={e=>setAvulsoNome(e.target.value)} className={cn(INPUT_CLS,"flex-1 min-w-[140px]")} />
                <Select value={avulsoLojaFilter} onValueChange={setAvulsoLojaFilter}>
                  <SelectTrigger className={cn(INPUT_CLS,"w-[150px]")}><SelectValue placeholder="Todas" /></SelectTrigger>
                  <SelectContent className={SEL_CONTENT}><SelectItem value="all">Todas</SelectItem>{stores.map(s=><SelectItem key={s.id} value={String(s.id)}>{s.nome}</SelectItem>)}</SelectContent>
                </Select>
                <Input type="date" value={avulsoDateStart} onChange={e=>setAvulsoDateStart(e.target.value)} className={cn(INPUT_CLS,"w-[145px]")} />
                <Input type="date" value={avulsoDateEnd}   onChange={e=>setAvulsoDateEnd(e.target.value)}   className={cn(INPUT_CLS,"w-[145px]")} />
                <button onClick={()=>{setAvulsoNome('');setAvulsoLojaFilter('all');setAvulsoDateStart('');setAvulsoDateEnd('');}} className="text-xs text-[#57715B] hover:underline font-medium">Limpar</button>
                <Button className={cn(BTN_PRIMARY,"ml-auto")} onClick={()=>setIsAvulsoDialogOpen(true)}>
                  <Plus className="h-4 w-4 mr-2"/>Registrar avulso
                </Button>
              </div>

              <div className="bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[32px] overflow-hidden shadow-lg shadow-[#57715B]/5">
                <div className="px-6 py-4 border-b border-[#57715B]/8">
                  <p className="font-semibold text-[#2D362E] dark:text-[#E6DCCF]">Trabalhos Avulsos</p>
                  <p className="text-xs text-[#8C7B6D] mt-0.5">Registros sem perfil cadastrado · {avulsos.length} resultado(s)</p>
                </div>
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-[#57715B]/8 hover:bg-transparent">
                        {['Nome','Data','Loja','Valor (R$)','Tipo','Evento','Setor','Obs'].map(h=>(
                          <TableHead key={h} className="text-[#8C7B6D] text-xs uppercase tracking-wider font-medium">{h}</TableHead>
                        ))}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {avulsos.length===0 ? (
                        <TableRow><TableCell colSpan={8} className="text-center py-12 text-[#8C7B6D]">Nenhum trabalho avulso encontrado</TableCell></TableRow>
                      ) : avulsos.map(a=>(
                        <TableRow key={a.id} className="border-[#57715B]/8 hover:bg-[#57715B]/3 transition-colors">
                          <TableCell className="font-medium text-[#2D362E] dark:text-[#E6DCCF]">{a.nome}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D]">{format(new Date(a.work_date),'dd/MM/yyyy')}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D]">{a.loja_id!=null?(storesMap[a.loja_id]||'—'):'—'}</TableCell>
                          <TableCell className="text-sm font-semibold text-[#57715B]">R$ {(a.valor_diaria||0).toFixed(2)}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D]">{a.local_tipo||'—'}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D] max-w-40 truncate">{a.evento_nome||'—'}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D]">{a.setor||'—'}</TableCell>
                          <TableCell className="text-sm text-[#8C7B6D] max-w-48 truncate">{a.observacao||'—'}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            </TabsContent>

            {/* ══ Tab Analytics ════════════════════════════════════════════ */}
            <TabsContent value="analytics" className="space-y-6 mt-4">
              {/* selector período */}
              <div className={cn(GLASS_FILTER,"flex flex-wrap items-center gap-3")}>
                <Calendar className="h-4 w-4 text-[#57715B] shrink-0" />
                <Select value={periodo} onValueChange={v=>setPeriodo(v as typeof periodo)}>
                  <SelectTrigger className={cn(INPUT_CLS,"w-[180px]")}><SelectValue /></SelectTrigger>
                  <SelectContent className={SEL_CONTENT}>
                    <SelectItem value="mes_atual">Mês atual</SelectItem>
                    <SelectItem value="mes_anterior">Mês anterior</SelectItem>
                    <SelectItem value="ultimos_7">Últimos 7 dias</SelectItem>
                    <SelectItem value="personalizado">Personalizado</SelectItem>
                  </SelectContent>
                </Select>
                {periodo==='personalizado' && (
                  <Popover>
                    <PopoverTrigger asChild>
                      <Button variant="outline" className={BTN_OUTLINE}>
                        <Calendar className="mr-2 h-4 w-4"/>
                        {periodoRange.from&&periodoRange.to?`${format(periodoRange.from,'dd/MM/yyyy')} — ${format(periodoRange.to,'dd/MM/yyyy')}`:'Selecionar intervalo'}
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-auto p-0 rounded-2xl border-[#57715B]/10" align="start">
                      <CalendarComponent mode="range" selected={periodoRange as any} onSelect={(r:any)=>setPeriodoRange(r||{})} initialFocus locale={ptBR} />
                    </PopoverContent>
                  </Popover>
                )}
              </div>

              {/* KPIs */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <KpiCard label="Total freelancers" value={totalFreelancers}             color="#57715B" sub={`${freelancersAtivos} ativos`} />
                <KpiCard label="Total pago"         value={`R$ ${totalPago.toFixed(0)}`} color="#33733F" sub="no período" />
                <KpiCard label="Média de dias"      value={mediaDias.toFixed(1)}          color="#B49364" sub="por freelancer" />
                <KpiCard label="Ativos"             value={freelancersAtivos}             color="#57715B" sub={totalFreelancers?`${((freelancersAtivos/totalFreelancers)*100).toFixed(0)}% do total`:'—'} />
              </div>

              {/* destaques */}
              <div className="grid gap-4 md:grid-cols-2">
                {([
                  { title:'Mais trabalhou', Icon:TrendingUp, pessoa:maisTrabalhou, valor:(maisTrabalhou?.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).length+' dias' },
                  { title:'Mais recebeu',   Icon:DollarSign, pessoa:maisRecebeu,   valor:'R$ '+((maisRecebeu?.diasDetalhados||[]).filter(d=>isWithinRange(d.data,rangeFrom,rangeTo)).reduce((s,d)=>s+d.valor,0)).toFixed(2) },
                ] as const).map(({title,Icon,pessoa,valor})=>(
                  <div key={title} className={cn(GLASS_CARD,"p-6")}>
                    <div className="flex items-center gap-3 mb-4">
                      <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center shrink-0">
                        <Icon className="h-5 w-5 text-[#57715B]" />
                      </div>
                      <p className="font-semibold text-[#2D362E] dark:text-[#E6DCCF]">{title}</p>
                    </div>
                    <p className="text-xl font-bold font-serif text-[#2D362E] dark:text-[#E6DCCF]">{pessoa?.nome??'—'}</p>
                    <p className="text-sm text-[#8C7B6D] mt-1">{valor}</p>
                  </div>
                ))}
              </div>
            </TabsContent>
          </Tabs>

          {/* ══ Dialog Editar ══════════════════════════════════════════════ */}
          <Dialog open={!!editFreelancer} onOpenChange={open=>!open&&setEditFreelancer(null)}>
            <DialogContent className="sm:max-w-[480px]">
              <DialogHeader><DialogTitle>Editar Freelancer</DialogTitle><DialogDescription>Atualize os dados cadastrais.</DialogDescription></DialogHeader>
              {editFreelancer && (
                <div className="grid gap-4 py-4">
                  {([['eNome','Nome','nome'],['eCpf','CPF','cpf'],['ePix','Chave PIX','chavePix']] as const).map(([id,label,field])=>(
                    <div key={id} className="grid gap-2"><Label>{label}</Label><Input id={id} className={INPUT_CLS} value={editFreelancer[field]} onChange={e=>setEditFreelancer({...editFreelancer,[field]:e.target.value})} /></div>
                  ))}
                  <div className="grid gap-2"><Label>Valor Diária (R$)</Label><Input type="number" className={INPUT_CLS} value={editFreelancer.valorDiaria} onChange={e=>setEditFreelancer({...editFreelancer,valorDiaria:Number(e.target.value)})} /></div>
                  <div className="grid gap-2">
                    <Label>Status</Label>
                    <Select value={editFreelancer.status} onValueChange={v=>setEditFreelancer({...editFreelancer,status:v as 'ativo'|'inativo'})}>
                      <SelectTrigger className={INPUT_CLS}><SelectValue /></SelectTrigger>
                      <SelectContent className={SEL_CONTENT}><SelectItem value="ativo">Ativo</SelectItem><SelectItem value="inativo">Inativo</SelectItem></SelectContent>
                    </Select>
                  </div>
                </div>
              )}
              <DialogFooter><Button variant="ghost" onClick={()=>setEditFreelancer(null)}>Cancelar</Button><Button className={BTN_PRIMARY} onClick={handleUpdateFreelancer}>Salvar</Button></DialogFooter>
            </DialogContent>
          </Dialog>

          {/* ══ Dialog Detalhes ════════════════════════════════════════════ */}
          <Dialog open={!!viewFreelancer} onOpenChange={open=>!open&&setViewFreelancer(null)}>
            <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
              <DialogHeader><DialogTitle>Detalhes do Freelancer</DialogTitle><DialogDescription>Histórico completo de dias trabalhados.</DialogDescription></DialogHeader>
              {viewFreelancer && (
                <div className="space-y-4 py-4">
                  <div className="grid grid-cols-2 gap-3">
                    {[['Nome',viewFreelancer.nome],['CPF',viewFreelancer.cpf],['Diária',`R$ ${viewFreelancer.valorDiaria.toFixed(2)}`],['PIX',viewFreelancer.chavePix]].map(([l,v])=>(
                      <div key={l} className="bg-[#57715B]/5 rounded-2xl p-3">
                        <p className="text-xs text-[#8C7B6D] uppercase tracking-wider mb-1">{l}</p>
                        <p className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] break-all">{v}</p>
                      </div>
                    ))}
                    <div className="bg-[#57715B]/5 rounded-2xl p-3"><p className="text-xs text-[#8C7B6D] uppercase tracking-wider mb-1">Recebido mês atual</p><p className="text-sm font-bold text-[#57715B]">R$ {totalRecebidoMesAtual(viewFreelancer).toFixed(2)}</p></div>
                    <div className="bg-[#57715B]/5 rounded-2xl p-3"><p className="text-xs text-[#8C7B6D] uppercase tracking-wider mb-1">Total histórico</p><p className="text-sm font-bold text-[#57715B]">R$ {(viewFreelancer.diasDetalhados||[]).reduce((s,d)=>s+d.valor,0).toFixed(2)}</p></div>
                  </div>
                  <div className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-md border border-[#57715B]/10 rounded-2xl overflow-hidden">
                    <Table>
                      <TableHeader><TableRow className="border-[#57715B]/8"><TableHead className="text-[#8C7B6D] text-xs">Data</TableHead><TableHead className="text-[#8C7B6D] text-xs">Loja</TableHead><TableHead className="text-right text-[#8C7B6D] text-xs">Valor</TableHead></TableRow></TableHeader>
                      <TableBody>
                        {(viewFreelancer.diasDetalhados||[]).sort((a,b)=>b.data.getTime()-a.data.getTime()).map((d,i)=>(
                          <TableRow key={i} className="border-[#57715B]/8 hover:bg-[#57715B]/3">
                            <TableCell className="text-sm">{format(d.data,'dd/MM/yyyy')}</TableCell>
                            <TableCell className="text-sm text-[#8C7B6D]">{d.lojaId!=null?(storesMap[d.lojaId]||'—'):'—'}</TableCell>
                            <TableCell className="text-right text-sm font-medium text-[#57715B]">R$ {d.valor.toFixed(2)}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </div>
              )}
              <DialogFooter>
                <Button variant="ghost" onClick={()=>setViewFreelancer(null)}>Fechar</Button>
                {viewFreelancer && (
                  <Button variant="outline" className={BTN_OUTLINE} onClick={()=>{
                    const wb=XLSX.utils.book_new();
                    XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{Nome:viewFreelancer.nome,CPF:viewFreelancer.cpf,Dias:(viewFreelancer.diasDetalhados||[]).length,'Total (R$)':+(viewFreelancer.diasDetalhados||[]).reduce((s,d)=>s+d.valor,0).toFixed(2),PIX:viewFreelancer.chavePix}]),'Resumo');
                    XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet((viewFreelancer.diasDetalhados||[]).map(d=>({Data:format(d.data,'yyyy-MM-dd'),Loja:d.lojaId!=null?(storesMap[d.lojaId]||''):'','Valor (R$)':+d.valor.toFixed(2)}))),'Detalhado');
                    XLSX.writeFile(wb,`freelancer_${viewFreelancer.nome.replace(/\s+/g,'_')}.xlsx`);
                  }}>
                    <Download className="h-4 w-4 mr-2"/>Excel
                  </Button>
                )}
              </DialogFooter>
            </DialogContent>
          </Dialog>

          {/* ══ Dialog Registrar Trabalho ══════════════════════════════════ */}
          <Dialog open={!!addWorkFreelancer} onOpenChange={open=>{if(!open)resetWorkDialog();}}>
            <DialogContent className="sm:max-w-[480px] max-h-[90vh] overflow-y-auto">
              <DialogHeader><DialogTitle>Registrar Trabalho</DialogTitle><DialogDescription>{addWorkFreelancer?`Dias e diária para ${addWorkFreelancer.nome}`:''}</DialogDescription></DialogHeader>
              <div className="grid gap-4 py-4">
                {addWorkFreelancer && (
                  <div className="bg-[#57715B]/5 rounded-2xl p-3 text-sm text-[#8C7B6D]">
                    <span className="font-medium">CPF:</span> {addWorkFreelancer.cpf} · <span className="font-medium">Diária sugerida:</span> R$ {addWorkFreelancer.valorDiaria.toFixed(2)}
                  </div>
                )}
                <div className="grid gap-2">
                  <Label>Local</Label>
                  <Select value={workLocalTipo} onValueChange={v=>setWorkLocalTipo(v as 'loja'|'evento')}>
                    <SelectTrigger className={INPUT_CLS}><SelectValue /></SelectTrigger>
                    <SelectContent className={SEL_CONTENT}><SelectItem value="loja">Loja</SelectItem><SelectItem value="evento">Evento</SelectItem></SelectContent>
                  </Select>
                </div>
                {workLocalTipo==='loja' && (
                  <div className="grid gap-2"><Label>Loja</Label>
                    <Select value={workLojaId} onValueChange={setWorkLojaId}>
                      <SelectTrigger className={INPUT_CLS}><SelectValue placeholder="Selecione a loja"/></SelectTrigger>

-- Tabela para registrar trabalhos avulsos (sem perfil de freelancer)
CREATE TABLE IF NOT EXISTS public.freelancer_avulso_work_days (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  nome text NOT NULL,
  work_date timestamptz NOT NULL,
  valor_diaria numeric NOT NULL DEFAULT 0,
  loja_id integer REFERENCES public.lojas(id) ON DELETE SET NULL,
  local_tipo text DEFAULT 'loja',
  evento_nome text NULL,
  setor text NULL,
  observacao text NULL,
  created_by uuid REFERENCES auth.users(id),
  created_at timestamptz DEFAULT now()
);

ALTER TABLE public.freelancer_avulso_work_days ENABLE ROW LEVEL SECURITY;

-- Políticas básicas: leitura liberada, inserção para usuários autenticados,
-- atualização e exclusão restritas ao criador
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'freelancer_avulso_work_days' AND policyname = 'Allow read for all'
  ) THEN
    CREATE POLICY "Allow read for all" ON public.freelancer_avulso_work_days
      FOR SELECT USING (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'freelancer_avulso_work_days' AND policyname = 'Allow insert for authenticated'
  ) THEN
    CREATE POLICY "Allow insert for authenticated" ON public.freelancer_avulso_work_days
      FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'freelancer_avulso_work_days' AND policyname = 'Allow update by creator'
  ) THEN
    CREATE POLICY "Allow update by creator" ON public.freelancer_avulso_work_days
      FOR UPDATE USING (created_by = auth.uid()) WITH CHECK (created_by = auth.uid());
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'freelancer_avulso_work_days' AND policyname = 'Allow delete by creator'
  ) THEN
    CREATE POLICY "Allow delete by creator" ON public.freelancer_avulso_work_days
      FOR DELETE USING (created_by = auth.uid());
  END IF;
END$$;

-- Índices para performance
CREATE INDEX IF NOT EXISTS idx_avulso_work_date ON public.freelancer_avulso_work_days(work_date);
CREATE INDEX IF NOT EXISTS idx_avulso_loja_id ON public.freelancer_avulso_work_days(loja_id);

