DO $$
DECLARE
  v_uid uuid;
  v_ok boolean;
BEGIN
  SELECT p.user_id INTO v_uid
  FROM profiles p JOIN user_roles r ON r.id=p.role_id
  WHERE lower(r.name)='rh_admin' LIMIT 1;

  RAISE NOTICE 'rh_admin uid = %', v_uid;
  RAISE NOTICE 'user_has_rbac_permission(view_funcionarios) = %', public.user_has_rbac_permission('view_funcionarios', v_uid);

  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_uid::text, 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  BEGIN
    INSERT INTO public.freelancers(nome,cpf,valor_diaria,chave_pix,status,created_by)
    VALUES('__rls_probe__','000.000.000-00',0,'probe@x',' ativo'::text, v_uid);
    RAISE NOTICE 'INSERT como rh_admin: SUCESSO (inesperado)';
  EXCEPTION WHEN others THEN
    RAISE NOTICE 'INSERT como rh_admin: BLOQUEADO -> % / %', SQLSTATE, SQLERRM;
  END;

  PERFORM set_config('role','postgres', true);
  RAISE EXCEPTION 'rollback probe';
EXCEPTION WHEN others THEN
  RAISE NOTICE 'probe finalizado: %', SQLERRM;
END$$;

