DO $$
BEGIN
  -- freelancers
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancers' AND policyname='RH/Admin veem todos os freelancers') THEN
    CREATE POLICY "RH/Admin veem todos os freelancers" ON public.freelancers
      FOR SELECT TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancers' AND policyname='RH/Admin inserem freelancers') THEN
    CREATE POLICY "RH/Admin inserem freelancers" ON public.freelancers
      FOR INSERT TO authenticated
      WITH CHECK (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancers' AND policyname='RH/Admin atualizam freelancers') THEN
    CREATE POLICY "RH/Admin atualizam freelancers" ON public.freelancers
      FOR UPDATE TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'))
      WITH CHECK (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancers' AND policyname='RH/Admin excluem freelancers') THEN
    CREATE POLICY "RH/Admin excluem freelancers" ON public.freelancers
      FOR DELETE TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  -- freelancer_work_days
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancer_work_days' AND policyname='RH/Admin veem todos os dias de trabalho') THEN
    CREATE POLICY "RH/Admin veem todos os dias de trabalho" ON public.freelancer_work_days
      FOR SELECT TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancer_work_days' AND policyname='RH/Admin atualizam dias de trabalho') THEN
    CREATE POLICY "RH/Admin atualizam dias de trabalho" ON public.freelancer_work_days
      FOR UPDATE TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'))
      WITH CHECK (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancer_work_days' AND policyname='RH/Admin excluem dias de trabalho') THEN
    CREATE POLICY "RH/Admin excluem dias de trabalho" ON public.freelancer_work_days
      FOR DELETE TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  -- freelancer_avulso_work_days
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancer_avulso_work_days' AND policyname='RH/Admin excluem qualquer avulso') THEN
    CREATE POLICY "RH/Admin excluem qualquer avulso" ON public.freelancer_avulso_work_days
      FOR DELETE TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='freelancer_avulso_work_days' AND policyname='RH/Admin atualizam qualquer avulso') THEN
    CREATE POLICY "RH/Admin atualizam qualquer avulso" ON public.freelancer_avulso_work_days
      FOR UPDATE TO authenticated
      USING (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'))
      WITH CHECK (public.is_admin_user() OR public.user_has_rbac_permission('view_funcionarios'));
  END IF;
END$$;

WITH u AS (
  SELECT p.user_id AS uid FROM profiles p JOIN user_roles r ON r.id=p.role_id WHERE lower(r.name)='rh_admin' LIMIT 1
)
SELECT
  public.is_admin_user(u.uid) AS rh_is_admin_user,
  public.user_has_rbac_permission('view_funcionarios', u.uid) AS rh_view_func,
  (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND policyname LIKE 'RH/Admin%') AS novas_policies
FROM u;

